for (const row of rows) {
  for (const source of new Set(row.aliases.filter(Boolean))) {
    catalogs.en[source] = row.en;
    catalogs.fr[source] = row.fr;
    catalogs.ar[source] = row.ar;
  }
}

for (const locale of ["en", "fr", "ar"]) {
  const sorted = Object.fromEntries(Object.entries(catalogs[locale]).sort(([a], [b]) => a.localeCompare(b)));
  fs.writeFileSync(path.join(root, "lib", "locales", `${locale}.json`), `${JSON.stringify(sorted, null, 2)}\n`);
}

console.log(`Migrated ${rows.length} AI experience translation groups.`);
